import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';

export interface MockConfig {
  type: 'mock';
  structuredResponses?: Map<string, unknown>;
}

export function createMockProvider(config?: MockConfig): AIProvider {
  const structuredResponses = config?.structuredResponses ?? new Map<string, unknown>();

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : 'Hello';

      const response = `Mock response to: "${userText}"`;

      for (const word of response.split(' ')) {
        yield {type: 'text', text: word + ' '};
      }

      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}};
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : '';

      const preconfigured = structuredResponses.get(userText);
      if (preconfigured !== undefined) return preconfigured as T;

      return buildDefaultResponse(params.responseSchema) as T;
    },
  };
}

// Factories, not values: `array` must hand back a fresh [] to each caller.
const SCALAR_DEFAULTS: Record<string, () => unknown> = {
  array: () => [],
  string: () => '',
  number: () => 0,
  boolean: () => false,
};

function buildDefaultResponse(schema: {type: string; properties?: Record<string, {type: string}>}): unknown {
  if (schema.type === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, prop] of Object.entries(schema.properties ?? {})) {
      result[key] = buildDefaultResponse(prop);
    }
    return result;
  }

  const scalar = SCALAR_DEFAULTS[schema.type];
  return scalar ? scalar() : null;
}
export interface PromptBuilderConfig {
  identity: string;
  domainContext?: string;
  responseGuidelines?: string;
  toolPreamble?: string;
}

export interface PromptBuilderOptions {
  toolInstructions?: string[];
  additionalContext?: string;
}

const DEFAULT_TOOL_PREAMBLE = `When users ask questions that relate to available tools, USE THE PROVIDED TOOLS to get accurate, real-time information.

IMPORTANT:
- Always use tools for specific data rather than guessing.
- If a tool call fails, explain the error and offer alternatives.
- Combine tool results with your knowledge to provide comprehensive answers.

CLARIFICATION RULE: If you are unsure which filter to apply or how to interpret the user's request, ASK the user for clarification BEFORE calling the tool.
When a question is clear and maps directly to known filters, proceed without asking.`;

export class PromptBuilder {
  constructor(private readonly config: PromptBuilderConfig) {}

  build(options: PromptBuilderOptions = {}): string {
    const {toolInstructions, additionalContext} = options;
    const parts: string[] = [this.config.identity];

    if (this.config.domainContext) {
      parts.push(this.config.domainContext);
    }

    if (toolInstructions?.length) {
      const preamble = this.config.toolPreamble ?? DEFAULT_TOOL_PREAMBLE;
      const numbered = toolInstructions.map((instruction, i) => `${i + 1}. ${instruction}`).join('\n\n');
      parts.push(`${preamble}\n\n${numbered}`);
    }

    if (this.config.responseGuidelines) {
      parts.push(`Response Guidelines:\n${this.config.responseGuidelines}`);
    }

    if (additionalContext) {
      parts.push(`Additional Context:\n${additionalContext}`);
    }

    return parts.join('\n\n');
  }
}
